script:
if doc.created_document and doc.created_document_type:
    linked = frappe.get_doc(doc.created_document_type, doc.created_document)
    if linked.docstatus == 1:
        linked.cancel()

now = frappe.utils.now_datetime()
docs = frappe.get_all('Quotation', filters={'docstatus': 0}, fields=['name', 'owner', 'customer_name', 'custom_موعد_المتابعة_القادمة_وقت', 'custom_followup_last_notified_at'])
for d in docs:
    due = d.get('custom_موعد_المتابعة_القادمة_وقت')
    if not due or due > now:
        continue
    last = d.get('custom_followup_last_notified_at')
    if last and due <= last:
        continue
    recipient = d.get('owner')
    subject = 'موعد متابعة عرض السعر ' + d.get('name')
    message = 'حان الآن موعد متابعة العرض ' + d.get('name') + ' للعميل ' + (d.get('customer_name') or '') + '. افتح العرض وسجل نتيجة المتابعة والموعد القادم.'
    try:
        log = frappe.get_doc({'doctype': 'Notification Log', 'subject': subject, 'for_user': recipient, 'type': 'Alert', 'document_type': 'Quotation', 'document_name': d.get('name'), 'email_content': message, 'from_user': 'Administrator'})
        log.insert(ignore_permissions=True)
    except Exception:
        pass
    try:
        email = frappe.db.get_value('User', recipient, 'email')
        if email:
            frappe.sendmail(recipients=[email], subject=subject, message=message)
    except Exception:
        pass
    frappe.db.set_value('Quotation', d.get('name'), 'custom_followup_last_notified_at', now, update_modified=False)
